from taf.ul.kpi_selector.operations.factory_prototype.classical_factory_prototype import OperationFactoryPrototype
from taf.ul.kpi_selector.operations.nr_rat_reset.classical_nr_rat_reset.nr_rat_reset_prototype import NrRatReset


class NrRatResetFactory(OperationFactoryPrototype):
    def __init__(self):
        super(NrRatResetFactory, self).__init__()

    def get_kpi(self):
        """
        Gets kpi for NR rat reset operation.
        :return: dictionary with timeout, requirement and operation description for NR rat reset
        :rtype: dict
        """
        return NrRatReset(self.bts).get_kpi()
